// Gaming PC showpiece, hand-made: real parts at their real sizes, their names printed as plain lettering (no logos). Units: cm.
// X: the case's depth (its glass front at +X, the back at -X), Y: up (floor 0), Z: its width; the side panel is off, the open side faces +Z.
// The motherboard hangs on the wall between the two chambers (z ≈ -5.9); the power supply and the cables live behind it.
const S = W.store;
S.white = W.paint('#e8ebee', { metallic: 0.15, rough: 0.38 });
S.whiteP = W.plastic('#eef0f2', { rough: 0.42 });
S.pcb = new THREE.MeshPhysicalMaterial({ color: 0x15191e, roughness: 0.55, metalness: 0.15, clearcoat: 0.4 });
S.silver = W.metal('#c6cacf', { rough: 0.26 });
S.gold = W.metal('gold', { rough: 0.3 });
S.rgbs = [];
S.fans = []; // the rotors that turn with the load: {rotor, k, label}
S.fan = (o = {}) => { // one 120 mm fan facing +Z: a frame, nine see-through blades, a light ring
  const g = W.group();
  const frame = new THREE.Shape();
  frame.moveTo(-6, -6); frame.lineTo(6, -6); frame.lineTo(6, 6); frame.lineTo(-6, 6); frame.lineTo(-6, -6);
  const hole = new THREE.Path(); hole.absarc(0, 0, 5.75, 0, Math.PI * 2, true); frame.holes.push(hole);
  g.add(new THREE.Mesh(new THREE.ExtrudeGeometry(frame, { depth: 2.3, bevelEnabled: true, bevelSize: 0.25, bevelThickness: 0.1, bevelSegments: 2, curveSegments: 32 }).translate(0, 0, -1.15), S.whiteP));
  const rotor = W.group();
  rotor.add(W.mesh(W.cyl(2, 2, 2.2, 32), S.whiteP, { rot: [90, 0, 0] }));
  const bs = new THREE.Shape();
  bs.moveTo(1.8, -0.9); bs.quadraticCurveTo(4.2, -1.8, 5.5, -0.4); bs.quadraticCurveTo(5.0, 1.4, 1.8, 1.0); bs.lineTo(1.8, -0.9);
  const bg = new THREE.ExtrudeGeometry(bs, { depth: 0.12, bevelEnabled: false, curveSegments: 10 }).translate(0, 0, -0.06);
  const bm = new THREE.MeshPhysicalMaterial({ color: 0xe9eef3, roughness: 0.35, transmission: 0.35, transparent: true, opacity: 0.9 });
  for (let i = 0; i < 9; i++) { const b = new THREE.Mesh(bg, bm); b.rotation.set(0.32, 0, (i / 9) * Math.PI * 2); rotor.add(b); }
  g.add(rotor);
  const glow = W.glow(o.light || '#5ab8ff', 1.8);
  g.add(W.mesh(W.torus(5.85, 0.17, 64, 6), glow, { at: [0, 0, 1.1] }));
  g.add(W.mesh(W.torus(5.85, 0.17, 64, 6), glow, { at: [0, 0, -1.1] }));
  S.rgbs.push(glow);
  S.fans.push({ rotor, k: o.k || 1, label: o.label || '' });
  return g;
};
// a flat strip along a path (the riser's ribbon cable), wide along `across`
S.ribbon = (pts, width, mat, across = [1, 0, 0]) => {
  const curve = new THREE.CatmullRomCurve3(pts.map((p) => new THREE.Vector3(p[0], p[1], p[2])));
  const n = 48, pos = [], idx = [];
  const sd = new THREE.Vector3(across[0], across[1], across[2]).normalize().multiplyScalar(width / 2);
  for (let i = 0; i <= n; i++) {
    const p = curve.getPoint(i / n);
    pos.push(p.x - sd.x, p.y - sd.y, p.z - sd.z, p.x + sd.x, p.y + sd.y, p.z + sd.z);
    if (i < n) { const a = i * 2; idx.push(a, a + 1, a + 2, a + 1, a + 3, a + 2); }
  }
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3)); g.setIndex(idx); g.computeVertexNormals();
  mat.side = THREE.DoubleSide;
  return new THREE.Mesh(g, mat);
};

const c = W.group();
const box = (w, h, d, x, y, z, m) => { const b = W.mesh(W.box(w, h, d, 0.2), m || S.white, { at: [x, y, z] }); c.add(b); return b; };
const roofless = []; // (the walls and the roof don't throw a shadow inside: the parts stay lit)
box(46.5, 1, 29, 0, 0.5, 0);                                         // the floor
const top = W.canvasTex(256, 64);
{ const g = top.ctx; g.fillStyle = '#e6e9ec'; g.fillRect(0, 0, 256, 64); g.fillStyle = '#9ba1a8';
  for (let y = 4; y < 64; y += 6) for (let x = (y / 6) % 2 ? 3 : 0; x < 256; x += 6) { g.beginPath(); g.arc(x, y, 1.9, 0, 6.283); g.fill(); } top.update(); }
top.texture.wrapS = top.texture.wrapT = THREE.RepeatWrapping; top.texture.repeat.set(4, 2);
const roof = W.mesh(W.box(46.5, 0.8, 29, 0.2), new THREE.MeshStandardMaterial({ map: top.texture, roughness: 0.55, metalness: 0.2 }), { at: [0, 45.5, 0] });
c.add(roof); roofless.push(roof);
roofless.push(box(0.8, 45, 29, -22.85, 22.9, 0));                                  // the back wall
roofless.push(box(46.5, 45, 0.4, 0, 22.9, -14.25));                                 // the rear chamber's outer panel
roofless.push(box(44, 44, 0.3, -0.5, 23, -5.85, W.paint('#dfe3e7', { metallic: 0.1, rough: 0.5 }))); // the wall between the chambers
for (const [x, z] of [[21.5, 13.4], [21.5, -13.4], [-21.5, 13.4], [-21.5, -13.4]]) roofless.push(box(1.4, 45, 1.4, x, 22.9, z));
const glass = W.glass({ tint: '#dfeeff', thickness: 0.4 });
const front = W.mesh(W.box(0.4, 43.6, 26, 0.1), glass, { at: [23.05, 23, 0] });   // the front glass
c.add(front); roofless.push(front);
for (const [x, z] of [[19, 11.5], [19, -11.5], [-19, 11.5], [-19, -11.5]]) c.add(W.mesh(W.cyl(1.6, 2, 1.4, 20), W.rubber(), { at: [x, -0.6, z] }));
const brand = W.text('LIAN LI', { size: 1.1, color: '#6b7178', spacing: 6 });
brand.position.set(0, 1.05, 14.52);
c.add(brand);
// a soft light inside, the way a lit build glows on a desk
const lamp = new THREE.PointLight(0xe4eeff, 900, 0, 2);
lamp.position.set(4, 36, 9);
c.add(lamp);
W.add(c, { label: 'కేస్ O11 Dynamic EVO', heat: [27, 33] });
for (const m of roofless) m.castShadow = false;
W.explodeView('front');

const S = W.store;
// ROG Strix X870E-E (ATX 30.5 × 24.4 cm) on the middle wall; its back-panel ports at the back (-X), the processor socket high up
const b = W.group({ at: [-9.2, 24.65, -5.62] });
b.add(W.mesh(W.box(24.4, 30.5, 0.16, 0.05), S.pcb));
const dark = W.metal('#23262b', { rough: 0.4 }), steel = W.metal('#9ea4ab', { rough: 0.3 });
b.add(W.mesh(W.box(4.6, 12, 3.4, 0.8), W.metal('#30343a', { rough: 0.35 }), { at: [-10.2, 7.8, 1.8] }));  // the back-panel cover
const strix = W.text('ROG STRIX', { size: 0.9, color: '#d8dce1', spacing: 2 });
strix.position.set(-10.2, 7.5, 3.55); strix.rotation.z = Math.PI / 2;
b.add(strix);
b.add(W.mesh(W.box(3.2, 8, 1.6, 0.5), dark, { at: [-6.6, 9.8, 0.9] }));          // power-stage heatsink, left of the socket
b.add(W.mesh(W.box(11, 2.6, 1.6, 0.5), dark, { at: [-1.4, 13.4, 0.9] }));        // power-stage heatsink, above the socket
b.add(W.mesh(W.box(2.4, 1, 1.2, 0.15), W.plastic('#15171a'), { at: [-7, 14.7, 0.65] })); // the processor's 8-pin power socket
for (const x of [6.4, 7.4, 8.4, 9.4]) b.add(W.mesh(W.box(0.6, 13.6, 0.7), W.plastic('#2b2f35'), { at: [x, 4.5, 0.4] })); // four memory slots
b.add(W.mesh(W.box(9.4, 1.2, 1.2, 0.2), steel, { at: [-3.2, -4.4, 0.6] }));      // the steel-armoured graphics slot
b.add(W.mesh(W.box(8.6, 5.6, 1.4, 0.6), dark, { at: [3.5, -8.4, 0.8] }));         // chipset heatsink
b.add(W.mesh(W.box(9.5, 5.2, 0.5, 0.3), dark, { at: [-3.4, -10.6, 0.35] }));      // lower M.2 covers
b.add(W.mesh(W.box(2.6, 5.4, 1.2, 0.2), W.plastic('#1b1d21'), { at: [11.2, 8, 0.6] })); // 24-pin socket
b.add(W.mesh(W.box(4.4, 4.4, 0.4, 0.1), W.plastic('#2d3036'), { at: [-1, 9, 0.25] }));   // the AM5 socket frame
b.add(W.mesh(W.box(8.6, 0.8, 0.3), W.plastic('#2d3036'), { at: [-2, 1.35, 0.2] }));        // the M.2 slot under the SSD
W.add(b, { label: 'మదర్‌బోర్డ్ ROG Strix X870E', explode: [-2, 0, 6], heat: [38, 62], layer: 3 });

const S = W.store;
// Ryzen 7 9800X3D: its metal lid (4 × 4 cm) with the name on it, in the AM5 socket; the cooler's pump sits on it
const cpu = W.group({ at: [-10.2, 33.65, -5.1] });
cpu.add(W.mesh(W.box(4, 4, 0.25, 0.05), W.plastic('#1f7a3a')));
const lid = new THREE.Shape();
lid.moveTo(-1.7, -1.45); lid.lineTo(-1.45, -1.7); lid.lineTo(1.45, -1.7); lid.lineTo(1.7, -1.45); lid.lineTo(1.7, 1.45); lid.lineTo(1.45, 1.7);
lid.lineTo(-1.45, 1.7); lid.lineTo(-1.7, 1.45); lid.lineTo(-1.7, -1.45);
cpu.add(new THREE.Mesh(new THREE.ExtrudeGeometry(lid, { depth: 0.35, bevelEnabled: true, bevelSize: 0.05, bevelThickness: 0.05 }).translate(0, 0, 0.1), S.silver));
const name = W.text('AMD RYZEN 7 9800X3D', { size: 0.3, color: '#3a3d42' });
name.position.set(0, 0.2, 0.53);
cpu.add(name);
W.add(cpu, { label: 'ప్రాసెసర్ Ryzen 7 9800X3D', explode: [-24, -6, 16], heat: [40, 78], layer: 3 });

const S = W.store;
// two G.Skill Trident Z5 RGB DDR5 sticks (13.3 × 4.4 cm), a light bar along the top of each
const mem = W.group();
for (const x of [-1.8, 0.2]) {
  const s = W.group({ at: [x, 29.15, -3.5] });
  s.add(W.mesh(W.box(0.75, 13.3, 3.6, 0.2), W.metal('#2c2f34', { rough: 0.3 })));
  s.add(W.mesh(W.box(0.8, 12, 0.6, 0.2), W.metal('#b6bbc1', { rough: 0.22 }), { at: [0, 0, 1] }));
  const bar = W.glow('#b87dff', 1.8);
  s.add(W.mesh(W.box(0.7, 12.8, 0.8, 0.3), bar, { at: [0, 0, 2.15] }));
  S.rgbs.push(bar);
  const t = W.text('TRIDENT Z5', { size: 0.5, color: '#e6e9ed', spacing: 2 });
  t.position.set(0.42, 0, -0.2); t.rotation.set(0, Math.PI / 2, Math.PI / 2);
  s.add(t);
  mem.add(s);
}
W.add(mem, { label: 'మెమరీ Trident Z5 DDR5', explode: [14, 8, 14], heat: [34, 52], layer: 2 });

const S = W.store;
// Samsung 990 PRO: an M.2 2280 stick (8 × 2.2 cm) in the slot under the processor
const d = W.group({ at: [-10.2, 26, -5.35] });
d.add(W.mesh(W.box(8, 2.2, 0.12, 0.03), W.plastic('#14161a')));
d.add(W.mesh(W.box(2.2, 1.5, 0.15, 0.03), W.plastic('#2b2f35'), { at: [-1.5, 0, 0.1] }));
d.add(W.mesh(W.box(1.4, 1.4, 0.15, 0.03), W.plastic('#2b2f35'), { at: [1.6, 0, 0.1] }));
const sticker = W.text('SAMSUNG 990 PRO', { size: 0.34, color: '#e8eaee', bg: '#20232a' });
sticker.position.set(0.4, 0, 0.2);
d.add(sticker);
d.add(W.mesh(W.box(0.5, 2.2, 0.15), S.gold, { at: [-4.1, 0, 0] }));
W.add(d, { label: 'SSD Samsung 990 PRO', explode: [-24, -8, 14], heat: [34, 58], layer: 2 });

const S = W.store;
const VARIANT = '5090';
// the card stands upright on its bracket, its two fans facing the open side; sizes of the Founders Edition cards
const SPEC = { 5090: { l: 30.4, h: 13.7, t: 4.8, w: 575, hot: 76 },
  5080: { l: 30.4, h: 13.7, t: 4.8, w: 360, hot: 70 },
  5070: { l: 24.2, h: 11.2, t: 4.2, w: 250, hot: 68 } }[VARIANT];
S.gpu = { name: 'RTX ' + VARIANT, watts: SPEC.w };
S.fans = (S.fans || []).filter((f) => !f.gpu); // (another card swapped in: the old card's fans leave with it)
const LABEL = 'గ్రాఫిక్స్ కార్డ్ RTX ' + VARIANT;
const cx = -12.1 + 0.2 * SPEC.l, cy = 3.6 + SPEC.h / 2; // (its slot fingers stay over the bracket whatever its length)
const card = W.group({ at: [cx, cy, 5.6] });
const shell = W.metal('#c3c7cc', { rough: 0.24 }), core = W.metal('#1c1e22', { rough: 0.38 });
card.add(W.mesh(W.box(SPEC.l, SPEC.h, SPEC.t * 0.5, 0.6), core));                                  // the dark middle body
for (const y of [-1, 1]) card.add(W.mesh(W.box(SPEC.l, 1.1, SPEC.t, 0.5), shell, { at: [0, y * (SPEC.h / 2 - 0.55), 0] }));
for (const x of [-1, 1]) card.add(W.mesh(W.box(1.1, SPEC.h, SPEC.t, 0.5), shell, { at: [x * (SPEC.l / 2 - 0.55), 0, 0] }));
const fr = SPEC.h * 0.36;
for (const x of [-SPEC.l * 0.29, SPEC.l * 0.29]) { // two fans, one at each end: air goes straight through the card
  const f = W.group({ at: [x, 0, SPEC.t / 2 - 0.4] });
  f.add(W.mesh(W.ring(fr, fr + 0.45, 0.6, 64), shell, { rot: [90, 0, 0] }));
  const r = W.group();
  const bs = new THREE.Shape();
  bs.moveTo(fr * 0.28, -0.6); bs.quadraticCurveTo(fr * 0.7, -1.4, fr * 0.98, -0.3); bs.quadraticCurveTo(fr * 0.8, 0.9, fr * 0.28, 0.7); bs.lineTo(fr * 0.28, -0.6);
  const bg = new THREE.ExtrudeGeometry(bs, { depth: 0.1, bevelEnabled: false });
  const bm = W.plastic('#24272c', { rough: 0.5 });
  for (let i = 0; i < 7; i++) { const m = new THREE.Mesh(bg, bm); m.rotation.set(0.35, 0, i / 7 * Math.PI * 2); r.add(m); }
  r.add(W.mesh(W.cyl(fr * 0.28, fr * 0.28, 0.5, 32), core, { rot: [90, 0, 0] }));
  f.add(r);
  S.fans.push({ rotor: r, k: 0.8, label: LABEL, gpu: true });
  card.add(f);
}
const lt = W.text('GEFORCE RTX ' + VARIANT, { size: 0.75, color: '#e9edf1', spacing: 3 });
lt.position.set(0, SPEC.h / 2 + 0.01, 0); lt.rotation.x = -Math.PI / 2;
card.add(lt);
const lt2 = W.text('RTX ' + VARIANT, { size: 0.9, color: '#e9edf1', spacing: 2 });
lt2.position.set(0, -SPEC.h * 0.36, SPEC.t / 2 + 0.01);
card.add(lt2);
card.add(W.mesh(W.box(1.8, 0.7, 1.2, 0.1), W.plastic('#15171a'), { at: [SPEC.l * 0.12, SPEC.h / 2 + 0.3, -0.6] })); // the 12V-2x6 socket
card.add(W.mesh(W.box(SPEC.l * 0.3, 0.6, 0.15), S.gold, { at: [-SPEC.l * 0.2, -SPEC.h / 2 - 0.3, -SPEC.t / 2 + 0.6] }));
W.add(card, { label: LABEL, explode: [10, -4, 22], heat: [34, SPEC.hot], layer: 1 });
W.sound({ kind: 'air', label: LABEL, gain: 0.7, f0: 900 });
// its 16-pin power cable, from the power supply behind the wall, up into the socket on the card's top edge
const px = cx + SPEC.l * 0.12, py = cy + SPEC.h / 2 + 0.7;
const pw = W.group();
const black = W.fabric('#1d1f23');
for (let i = 0; i < 4; i++) {
  const o = (i - 1.5) * 0.36;
  pw.add(W.mesh(W.tube([[px - 4 + o, 6, -9], [px - 1 + o, 5.5, -6.6], [px + o, 7, -2], [px + 1.6 + o, py + 2.2, 1.5], [px + o, py + 1.4, 4.4], [px + o, py, 5.0]], 0.19, 40), black));
}
W.add(pw, { label: 'GPU పవర్ కేబుల్ 12V-2x6', explode: [10, 2, 16], layer: 2 });

const S = W.store;
// the card's bracket on the floor, and the flat riser cable from the board's graphics slot down to it
const r = W.group();
r.add(W.mesh(W.box(10.5, 1.6, 2.2, 0.2), W.plastic('#2a2d33'), { at: [-12.1, 2.6, 4.1] }));
r.add(S.ribbon([[-12.4, 20.2, -4.6], [-12.4, 19.2, -2.4], [-12.8, 13, -1.0], [-12.6, 5, 0.2], [-12.2, 2.6, 2.4]], 6.4, W.plastic('#2a2d33', { rough: 0.6 })));
W.add(r, { label: 'రైజర్ కేబుల్', explode: [-8, 0, 12], layer: 2 });

const S = W.store;
// NZXT Kraken Elite 360: the pump head with its round 2.72" screen on the processor, two sleeved tubes, the 401 mm radiator on the roof
const pump = W.group({ at: [-10.2, 33.65, 0] });
pump.add(W.mesh(W.cyl(3.0, 3.0, 1.2, 48), W.metal('#2a2d32', { rough: 0.35 }), { at: [0, 0, -4.3], rot: [90, 0, 0] }));
pump.add(W.mesh(W.cyl(3.95, 3.95, 3.6, 64), S.white, { at: [0, 0, -1.8], rot: [90, 0, 0] }));
const scr = W.canvasTex(256, 256);
const lcdMat = new THREE.MeshStandardMaterial({ map: scr.texture, emissiveMap: scr.texture, emissive: 0xffffff, emissiveIntensity: 1.1, roughness: 0.15 });
pump.add(W.mesh(new THREE.CircleGeometry(3.3, 64), lcdMat, { at: [0, 0, 0.03] }));
const rim = W.glow('#5ab8ff', 1.4);
pump.add(W.mesh(W.torus(3.62, 0.14, 64, 8), rim, { at: [0, 0, 0.02] }));
S.rgbs.push(rim);
S.lcd = (temp, warn) => { // the screen shows the processor's temperature: a ring that fills with it
  const g = scr.ctx;
  g.fillStyle = '#05070a'; g.fillRect(0, 0, 256, 256);
  g.lineWidth = 16; g.lineCap = 'round';
  g.strokeStyle = 'rgba(255,255,255,0.08)'; g.beginPath(); g.arc(128, 128, 104, 0.75 * Math.PI, 2.25 * Math.PI); g.stroke();
  const k = Math.max(0, Math.min(1, (temp - 25) / 70));
  const col = warn || temp > 85 ? '#ff5a3c' : temp > 70 ? '#ffb23c' : '#5ab8ff';
  g.strokeStyle = col; g.beginPath(); g.arc(128, 128, 104, 0.75 * Math.PI, (0.75 + 1.5 * k) * Math.PI); g.stroke();
  g.fillStyle = '#f2f6fa'; g.font = '700 92px system-ui, sans-serif'; g.textAlign = 'center'; g.textBaseline = 'middle';
  g.fillText(Math.round(temp) + '°', 136, 124);
  g.fillStyle = col; g.font = '600 26px system-ui, sans-serif'; g.fillText(warn ? '! FAN' : 'CPU', 128, 190);
  scr.update();
};
S.lcd(38);
W.add(pump, { label: 'కూలర్ పంప్ NZXT Kraken', explode: [-14, 8, 22], heat: [32, 48], layer: 1 });
const tubes = W.group();
const sleeve = W.fabric('#e3e6e9');
tubes.add(W.mesh(W.tube([[-11.6, 37.2, -1.8], [-13, 39.4, 0.5], [-16.5, 41, 1.6], [-18.1, 42.2, 2.2]], 0.6, 40), sleeve));
tubes.add(W.mesh(W.tube([[-8.8, 37.2, -1.8], [-9.5, 40, 2.4], [-14.5, 41.2, 6.4], [-18.1, 42.2, 6.8]], 0.6, 40), sleeve));
W.add(tubes, { label: 'కూలర్ పైపులు', explode: [-6, 10, 12], heat: [32, 46], layer: 1 });
const rad = W.group({ at: [1.5, 43.7, 4.5] });
rad.add(W.mesh(W.box(40.1, 2.7, 12, 0.3), S.white));
const fins = W.canvasTex(256, 32);
{ const g = fins.ctx; for (let x = 0; x < 256; x += 2) { g.fillStyle = x % 4 ? '#c9ced3' : '#f2f4f6'; g.fillRect(x, 0, 2, 32); } fins.update(); }
fins.texture.wrapS = THREE.RepeatWrapping; fins.texture.repeat.set(10, 1);
rad.add(W.mesh(W.box(35.6, 2.75, 11.4), new THREE.MeshStandardMaterial({ map: fins.texture, roughness: 0.6, metalness: 0.3 }), { at: [1.6, 0, 0] }));
const nz = W.text('NZXT', { size: 1.3, color: '#2a2e33', spacing: 8 });
nz.position.set(15, 0, 6.02);
rad.add(nz);
W.add(rad, { label: 'రేడియేటర్', explode: [0, 14, 6], heat: [30, 47], layer: 0 });

const S = W.store;
// three under the radiator (blow out through the roof), three on the front side (pull fresh air in), one at the back (blows out)
const topF = W.group(), sideF = W.group(), rearF = W.group();
for (let i = 0; i < 3; i++) {
  const f = S.fan({ label: 'పై ఫ్యాన్లు' }); f.position.set(-10.9 + i * 12.4, 40.7, 4.5); f.rotation.x = Math.PI / 2; topF.add(f);
  const s = S.fan({ label: 'పక్క ఫ్యాన్లు' }); s.position.set(20.6, 8 + i * 12.4, 4.5); s.rotation.y = -Math.PI / 2; sideF.add(s);
}
const rf = S.fan({ label: 'వెనక ఫ్యాన్' }); rf.position.set(-21.6, 35, 4.5); rf.rotation.y = Math.PI / 2; rearF.add(rf);
W.add(topF, { label: 'పై ఫ్యాన్లు', explode: [0, 7, 6], heat: [30, 40], layer: 0 });
